#pragma once

// Synthetic SNES ROMs shaped like TMNT IV's sound tables, made from generated bytes only.

#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

#include "classic_soundtrack/snes_rom.h"
#include "classic_soundtrack/sound_parser.h"
#include "classic_soundtrack/soundset.h"

namespace classic_fixture {

using namespace tmnt::classic;
using Bytes = std::vector<std::uint8_t>;

struct Ptr {
  std::uint16_t address = 0;
  std::uint8_t bank = 0;
};

constexpr size_t kSongTableOffset = 0x10000 + 0x38E8;
constexpr size_t kPackTableOffset = 0x10000 + 0x395D;
constexpr size_t kBootListOffset = 0x10000 + 0x39BD;
constexpr size_t kStageTableOffset = 0x9409;

inline Bytes LzLiteral(const Bytes& data) {
  Bytes body;
  for (size_t at = 0; at < data.size(); at += 31) {
    const size_t n = std::min<size_t>(31, data.size() - at);
    body.push_back(std::uint8_t(0x80 | n));
    body.insert(body.end(), data.begin() + at, data.begin() + at + n);
  }
  const size_t total = body.size() + 2;
  Bytes out{std::uint8_t(total), std::uint8_t(total >> 8)};
  out.insert(out.end(), body.begin(), body.end());
  return out;
}

inline Bytes Pattern(size_t size, int seed) {
  Bytes bytes(size);
  for (size_t i = 0; i < size; ++i) {
    bytes[i] = std::uint8_t(0x30 + (i * 7 + size_t(seed) * 13) % 0x50);
  }
  return bytes;
}

inline void FixChecksum(Bytes& rom) {
  rom[0x7FDC] = rom[0x7FDD] = 0xFF;
  rom[0x7FDE] = rom[0x7FDF] = 0;
  std::uint32_t sum = 0;
  for (const std::uint8_t byte : rom) {
    sum += byte;
  }
  const std::uint16_t checksum = std::uint16_t(sum);
  const std::uint16_t complement = std::uint16_t(~checksum);
  rom[0x7FDC] = std::uint8_t(complement);
  rom[0x7FDD] = std::uint8_t(complement >> 8);
  rom[0x7FDE] = std::uint8_t(checksum);
  rom[0x7FDF] = std::uint8_t(checksum >> 8);
}

class RomBuilder {
 public:
  explicit RomBuilder(int seed = 0) : rom_(kRomSize, 0), seed_(seed) {
    WriteHeader();
    WriteBoot();
    WriteSongs();
    WritePacks();
    WriteStages();
    FixChecksum(rom_);
  }

  Bytes rom() const { return rom_; }

 private:
  Ptr PutRaw(const Bytes& data) {
    const Ptr ptr = Here();
    const size_t length = data.size() + 2;
    rom_[cursor_++] = std::uint8_t(length);
    rom_[cursor_++] = std::uint8_t(length >> 8);
    std::copy(data.begin(), data.end(), rom_.begin() + cursor_);
    cursor_ += data.size();
    return ptr;
  }

  Ptr PutLz(const Bytes& data) {
    const Ptr ptr = Here();
    const Bytes stream = LzLiteral(data);
    std::copy(stream.begin(), stream.end(), rom_.begin() + cursor_);
    cursor_ += stream.size();
    return ptr;
  }

  Ptr Here() const { return {std::uint16_t(0x8000 + cursor_ % 0x8000), std::uint8_t(cursor_ / 0x8000)}; }

  void SetPointer(size_t at, Ptr ptr, std::uint8_t flags) {
    rom_[at] = std::uint8_t(ptr.address);
    rom_[at + 1] = std::uint8_t(ptr.address >> 8);
    rom_[at + 2] = std::uint8_t(ptr.bank | flags);
  }

  void WriteHeader() {
    const char title[] = "SYNTHETIC TEST ROM";
    std::copy(title, title + sizeof(title) - 1, rom_.begin() + 0x7FC0);
    rom_[0x7FD5] = 0x20;
    rom_[0x7FD7] = 10;
    rom_[0x7FD9] = 1;
  }

  void WriteBoot() {
    const struct {
      std::uint16_t dest;
      Bytes data;
      bool raw;
    } blocks[] = {
        {0x0400, Pattern(40, seed_ + 1), false},
        {0x3E00, BrrBlocks(3), true},
        {0x6100, Pattern(18, seed_ + 2), true},
        {0xFE00, Pattern(16, seed_ + 3), true},
    };
    size_t at = kBootListOffset;
    rom_[at++] = 0x02;
    rom_[at++] = 0x00;
    for (const auto& block : blocks) {
      rom_[at] = std::uint8_t(block.dest);
      rom_[at + 1] = std::uint8_t(block.dest >> 8);
      SetPointer(at + 2, block.raw ? PutRaw(block.data) : PutLz(block.data), block.raw ? 0x80 : 0);
      at += 5;
    }
    rom_[at] = 0x01;
    rom_[at + 1] = 0x00;
  }

  static Bytes BrrBlocks(size_t count) {
    Bytes bytes;
    for (size_t i = 0; i < count; ++i) {
      bytes.push_back(0x01);
      for (int j = 0; j < 8; ++j) {
        bytes.push_back(std::uint8_t(0x11 * (j + 1)));
      }
    }
    return bytes;
  }

  void WriteSongs() {
    for (size_t i = 0; i < kSongCount; ++i) {
      const Bytes data = Pattern(20 + i, seed_ + int(i));
      SetPointer(kSongTableOffset + i * 3, PutLz(data), i % 3 == 1 ? 0x80 : 0);
    }
  }

  void WritePacks() {
    for (size_t i = 0; i < kPackCount; ++i) {
      const size_t record = kPackTableOffset + i * 8;
      const Bytes dir = {0x00, 0x3E, 0x00, 0x3E, 0x09, 0x3E, 0x09, 0x3E, 0x12, 0x3E, 0x12, 0x3E};
      SetPointer(record, PutRaw(BrrBlocks(3)), 0xC0);
      SetPointer(record + 3, PutRaw(dir), 0);
      rom_[record + 6] = std::uint8_t(0x70 + i);
    }
  }

  void WriteStages() {
    for (size_t stage = 0; stage < kStageCount; ++stage) {
      const std::uint16_t value = stage == kStageCount - 1 ? kNoId : std::uint16_t(stage * 3 * 3);
      rom_[kStageTableOffset + stage * 2] = std::uint8_t(value);
      rom_[kStageTableOffset + stage * 2 + 1] = std::uint8_t(value >> 8);
    }
  }

  Bytes rom_;
  int seed_;
  size_t cursor_ = 0x20000;
};

inline std::string FingerprintOf(const Bytes& rom) {
  const ParseResult parsed = ParseSoundSet(rom);
  return parsed.category == ParseCategory::kOk ? SoundtrackFingerprint(parsed.set) : std::string();
}

}  // namespace classic_fixture
